// [vite-esm] imports auto-generated by the 2026-07 Vite migration.
import "../state.js";

/**
 * SubjectLegend — what does "MA" mean?
 *
 * The grid cannot spell subject names: a compact cell is ~24px of text, so
 * cards show a 2–4 character code. That is unavoidable at this density, but the
 * product shipped with NO decoder anywhere (grep "legend" index.html = 0 hits),
 * so a new user saw 25 distinct codes and no way to resolve them except
 * hovering one card at a time.
 *
 * The codes are also width-dependent: autoFitSubjectCodes() canvas-measures each
 * label and shrinks it until it fits (MATHS -> Math -> Mat -> Ma). So rather
 * than re-deriving codes here — which would drift from what is painted — this
 * legend reads the codes STRAIGHT OFF THE RENDERED DOM. Whatever the grid is
 * showing is what the legend lists, by construction, at every density and
 * colour axis.
 *
 * Colours come from the same inline --chrx-card-hue the cards use.
 */
window.SubjectLegend = (function () {
  "use strict";

  let panel = null;
  let button = null;

  // One entry per distinct rendered cell label. Reads the live DOM so the legend
  // can never disagree with the grid.
  function collect() {
    const editor = document.querySelector(".chrx-editor");
    if (!editor) return [];

    const S = window.APP && window.APP.school;
    const byLesson = (S && S._idx && S._idx.lessonById) ||
      Object.fromEntries(((S && S.lessons) || []).map(function (l) { return [l.id, l]; }));
    const bySubject = (S && S._idx && S._idx.subjectById) ||
      Object.fromEntries(((S && S.subjects) || []).map(function (s) { return [s.id, s]; }));
    const seen = new Map();

    editor.querySelectorAll(".chrx-vkarta").forEach(function (vk) {
      const line1 = vk.querySelector(".chrx-vk-line1");
      const code = line1 && line1.textContent.trim();
      if (!code) return;

      // The vkarta is keyed to a lesson via its closest slot/card attributes.
      const lessonId = vk.dataset.lessonId || (vk.closest("[data-lesson-id]") || {}).dataset?.lessonId;
      const lesson = lessonId ? byLesson[lessonId] : null;
      const subjectId = (lesson && lesson.subjectId) || vk.dataset.subjectId;
      const subject = subjectId ? bySubject[subjectId] : null;

      const key = code + "|" + (subjectId || "");
      if (seen.has(key)) return;

      const hue = (vk.style.getPropertyValue("--chrx-card-hue") || "").trim();
      seen.set(key, {
        code: code,
        // Prefer the school's own full name; fall back to whatever we can read.
        name: (subject && subject.name) || code,
        hue: hue,
      });
    });

    return Array.from(seen.values()).sort(function (a, b) {
      return a.code.localeCompare(b.code);
    });
  }

  function render() {
    if (!panel) return;
    const items = collect();
    const body = panel.querySelector(".chrx-legend__body");
    if (!body) return;

    if (!items.length) {
      body.innerHTML = '<p class="chrx-legend__empty">No cards on the grid yet.</p>';
      return;
    }

    body.innerHTML = items.map(function (it) {
      const swatch = it.hue
        ? '<span class="chrx-legend__swatch" style="--hue:' + esc(it.hue) + '"></span>'
        : '<span class="chrx-legend__swatch chrx-legend__swatch--none"></span>';
      // Only show the name when it actually adds information (a code that
      // already spells the name is noise).
      const name = it.name && it.name.toUpperCase() !== it.code.toUpperCase()
        ? '<span class="chrx-legend__name">' + esc(it.name) + "</span>"
        : '<span class="chrx-legend__name chrx-legend__name--same">full name</span>';
      return (
        '<li class="chrx-legend__row">' + swatch +
        '<span class="chrx-legend__code">' + esc(it.code) + "</span>" +
        name +
        "</li>"
      );
    }).join("");
  }

  function open() {
    if (!panel) return;
    panel.hidden = false;
    if (button) button.setAttribute("aria-expanded", "true");
    render();
  }

  function close() {
    if (!panel) return;
    panel.hidden = true;
    if (button) button.setAttribute("aria-expanded", "false");
  }

  function toggle() {
    if (!panel) return;
    if (panel.hidden) open(); else close();
  }

  function isOpen() {
    return !!(panel && !panel.hidden);
  }

  function build() {
    if (panel) return;

    button = document.getElementById("editor-legend");
    if (!button) return;

    panel = document.createElement("div");
    panel.className = "chrx-legend";
    panel.id = "chrx-legend-panel";
    panel.hidden = true;
    panel.setAttribute("role", "dialog");
    panel.setAttribute("aria-label", "Subject code legend");
    panel.innerHTML =
      '<div class="chrx-legend__head">' +
        '<span class="chrx-legend__title">Subject codes</span>' +
        '<button type="button" class="chrx-legend__x" aria-label="Close legend">\u00d7</button>' +
      "</div>" +
      '<ul class="chrx-legend__body"></ul>' +
      '<p class="chrx-legend__foot">Codes shorten automatically to fit the cell. Hover any card for its full details.</p>';
    document.body.appendChild(panel);

    button.setAttribute("aria-expanded", "false");
    button.setAttribute("aria-controls", "chrx-legend-panel");
    button.addEventListener("click", function (e) {
      e.preventDefault();
      e.stopPropagation();
      toggle();
    });

    panel.querySelector(".chrx-legend__x").addEventListener("click", close);

    // Click-away and Escape, matching the rest of the editor's overlays.
    document.addEventListener("pointerdown", function (e) {
      if (!isOpen()) return;
      if (panel.contains(e.target) || (button && button.contains(e.target))) return;
      close();
    }, true);
    document.addEventListener("keydown", function (e) {
      if (e.key === "Escape" && isOpen()) {
        e.preventDefault();
        close();
        if (button) button.focus();
      }
    });

    // The grid is rebuilt from HTML on every render/density/colour change, but
    // the codes are written after that by autoFitSubjectCodes(). Re-read on the
    // events that can change them, and only while the panel is actually open.
    ["editor:place", "editor:pickup", "entity:changed", "step:changed"].forEach(function (evt) {
      document.addEventListener(evt, function () {
        if (isOpen()) setTimeout(render, 0);
      });
    });
  }

  function esc(s) {
    return String(s == null ? "" : s).replace(/[&<>"']/g, function (c) {
      return { "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c];
    });
  }

  return { build: build, open: open, close: close, toggle: toggle, collect: collect, isOpen: isOpen };
})();

// [vite-esm] exports auto-generated by the 2026-07 Vite migration.
export const SubjectLegend = window.SubjectLegend;
